Ant Design Pro中的多个环境变量文件在Vue项目中我们会发现，有环境文件.env文件，可以配置生产和调试环境下的不同环境变量，在antdpro中该如何做到呢？接下来我们就来看看如何在项目中添加环境变量。
在antdpro项目中有config文件夹，里面是项目的配置信息，因为环境变量是在node环境中词啊可以访问到，所以antdpro提供了defined配置项，我们只需要将所需变量写到改配置项下面就可以在其他非node环境中使用，如下：
//config/config.ts define: &#123;    API_URL: &#x27;/dev-api&#x27;,    MQTT_URL: &#x27;wss://www.example.com/mqtt&#x27;,    MQTT_USERNAME: &#x27;hzpc&#x27;,    MQTT_PASSWORD: &#x27;123456&#x27;  &#125;,

然后我们在app.tsx 中就可以访问到
//app.tsxexport const request = &#123;  baseURL: API_URL,  timeout: 50000,  ...errorConfig,&#125;;

如果我们需要生产环境，同样的在config文件夹下增加config.prod.ts文件输入配置项就可以了
export default &#123;    define: &#123;        API_URL: &#x27;/prod-api&#x27;,        NAME: &#x27;aa&#x27;    &#125;&#125;

代理文件proxy.ts
/** * @name 代理的配置 * @see 在生产环境 代理是无法生效的，所以这里没有生产环境的配置 */export default &#123;  // 如果需要自定义本地开发服务器  请取消注释按需调整  dev: &#123;    // localhost:8000/api/** -&gt; https://preview.pro.ant.design/api/**    &#x27;/dev-api&#x27;: &#123;      // 要代理的地址      target: &#x27;http://172.16.36.55:8080&#x27;,//后端地址      // 配置了这个可以从 http 代理到 https      // 依赖 origin 的功能可能需要这个，比如 cookie      changeOrigin: true,      pathRewrite: &#123; &#x27;^/dev-api&#x27;: &#x27;&#x27; &#125;,    &#125;,  &#125;,  /**   * @name 详细的代理配置   * @doc https://github.com/chimurai/http-proxy-middleware   */  test: &#123;    // localhost:8000/api/** -&gt; https://preview.pro.ant.design/api/**    &#x27;/api&#x27;: &#123;      target: &#x27;https://proapi.azurewebsites.net&#x27;,      changeOrigin: true,      pathRewrite: &#123; &#x27;^/dev-api&#x27;: &#x27;&#x27; &#125;,    &#125;,  &#125;,  pre: &#123;    &#x27;/api/&#x27;: &#123;      target: &#x27;your pre url&#x27;,      changeOrigin: true,      pathRewrite: &#123; &#x27;^&#x27;: &#x27;&#x27; &#125;,    &#125;,  &#125;,  prod: &#123;    &#x27;/prod-api&#x27;: &#123;      target: &#x27;http://xxx.xxx.xxx.xxx:8000&#x27;,      changeOrigin: true,      pathRewrite: &#123; &#x27;^/prod-api&#x27;: &#x27;&#x27; &#125;,    &#125;  &#125;&#125;;



启动项目使用不同的命令
npm run dev使用的就是开发环境变量，对应的网络请求base_url是/dev-api，代理替换的地址是http://172.16.36.55:8080,而npnm run dev:prod，则使用的是生产环境的变量，对应的网络请求base_url是/peod-api，代理的地址是http&quot;//xxx.xxx.xxx:8000。

C语言存储类存储类定义C程序中变量&#x2F;函数的范围（可见性）和生命周期。这些说明符放在它们所修饰的类型前之前。
1. auto 存储类auto存储类是所有局部变量默认的存储类。
&#123;    int mount;    auto int month;&#125;

auto只能用在函数内，即auto只能修饰局部变量。

2. register 存储类register存储类用于定义存储在寄存器中而不是arm中的局部变量。这意味着变量的最大尺寸等于寄存器的大小（通常是一个字节），且不能对它应用一元的 ‘&amp;’ 运算符（因为它没有内存位置）。
&#123;   register int  miles;&#125;

3. static 存储类static 存储类指示编译器在程序的生命周期内保持局部变量的存在，而不需要在每次它进入和离开作用域时进行创建和销毁。因此，使用 static 修饰局部变量可以在函数调用之间保持局部变量的值。
static 修饰符也可以应用于全局变量。当 static 修饰全局变量时，会使变量的作用域限制在声明它的文件内。
在 C 编程中，当 static 用在类数据成员上时，会导致仅有一个该成员的副本被类的所有对象共享。
#include &lt;stdio.h&gt; /* 函数声明 */void func(void); static int count = 5; /* 全局变量 */ main()&#123;   while(count--)   &#123;      func();   &#125;   return 0;&#125;/* 函数定义 */void func( void )&#123;   static int i = 5; /* 局部静态变量 */   i++;   printf(&quot;i is %d and count is %d\n&quot;, i, count);&#125;

4. extern 存储类extern 存储类用于提供一个全局变量的引用，全局变量对所有的程序文件都是可见的。当您使用 ‘extern’ 时，对于无法初始化的变量，会把变量名指向一个之前定义过的存储位置。
当您有多个文件且定义了一个可以在其他文件中使用的全局变量或函数时，可以在其他文件中使用 extern 来得到已定义的变量或函数的引用。可以这么理解，extern 是用来在另一个文件中声明一个全局变量或函数。
extern 修饰符通常用于当有两个或多个文件共享相同的全局变量或函数的时候，如下所示：
第一个文件：main.c
#include &lt;stdio.h&gt; int count ;extern void write_extern(); main()&#123;   count = 5;   write_extern();&#125;
第二个文件：support.c
#include &lt;stdio.h&gt; extern int count; void write_extern(void)&#123;   printf(&quot;count is %d\n&quot;, count);&#125;
在这里，第二个文件中的 extern 关键字用于声明已经在第一个文件 main.c 中定义的 count。现在 ，编译这两个文件，如下所示：
 $gcc main.c support.c
这会产生 a.out 可执行程序，当程序被执行时，它会产生下列结果：
count is 5

HAL库常用一、GPIO通用// 1. 写引脚：置1/0   HAL_GPIO_WritePin(GPIOx,GPIO_Pin,GPIO_PIN_SET); //置高   HAL_GPIO_WritePin(GPIOx,GPIO_Pin,GPIO_PIN_RESET); //置低// 2. 读取引脚电平   GPIO_PinState state = HAL_GPIO_ReadPin(GPIOx,GPIO_Pin);// 3. 反转电平   HAL_GPIO_TogglePin(GPIOx,GPIO_Pin);// 4. 毫秒延时   HAL_Delay(ms);



二、UART串口1. 阻塞收发//发送数据HAL_UART_Transmit(&amp;huart1,dart,len,100);//接收数据HAL_UART_Receive(&amp;huart1,data,len,100);

2. 中断收发// 开启接收中断HAL_UART_Receive_IT(&amp;huart1,&amp;rxBuffer,1);

3. 中断回调函数void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)&#123;  if(huart == &amp;huart1)  &#123;    //处理收到的数据    //重新开启接收中断（必须写）    HAL_UART_Receive_IT(&amp;huart1,&amp;rxBuffer,1);  &#125;&#125;

4. printf重定向int fputc(int ch, FILE *f)&#123;  HAL_UART_Transmit(&amp;huart1,(uint8_t *)&amp;ch,1,100);  return ch;&#125;

三、定时器TIM（定时 + PWM）1. 开启定时器中断HAL_TIM_Base_Start_IT(&amp;htim2);

2. 定时器中断回调void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim)&#123;  if(htim == &amp;htim2)  &#123;    //定时任务  &#125;&#125;

3. PWM输出（呼吸灯、电机）//开启PWMHAL_TIM_PWM_start(&amp;htim3, TIM_CHANNEL_1);//修改占空比（0~65535）__HAL_TIM_SETCOMPARE(&amp;htim3,TIM_CHANNEL_1,val);

四、ADC数模转换（读模拟量）1. 单次采集HAL_ADC_Start(&amp;hadc1);HAL_ADC_PollForConversion(&amp;hadc1,100);int val = HAL_ADC_GetValue(&amp;hadc1);

2. DMA采集（不占CPU）HAL_ADC_Start_DMA(&amp;hadc1, buf, len);

五、DMA数据搬运（高效必备）//串口DMA发送HAL_UART_Transmit_DMA(&amp;huart,data,len);

六、I2C（OLED、传感器）//写数据HAL_I2C_Mem_Write(&amp;hi2c1, addr, reg, 1, data, len, 100);//读数据HAL_I2C_Mem_Read(&amp;hi2c1, add, reg, 1, data, len, 100);

七、中断通用（EXIT外部中断）void HAL_GPIO_EXIT_Callback(uint16_t GPIO_Pin)&#123;  if(GPIO_Pin == KEY_Pin)  &#123;    //按键触发  &#125;&#125;

八、常用宏// 使能/失能中断__enable_irq();__disable_irq();// 获取系统时钟HAL_GetTick();  // 返回开机毫秒数// 位操作SET_BIT(REG, BIT);CLEAR_BIT(REG, BIT);READ_BIT(REG, BIT);

1. HAL_GPIO_WritePin2. HAL_GPIO_ReadPin3. HAL_GPIO_TogglePin4. HAL_Delay5. HAL_UART_Transmit6. HAL_UART_Receive7. HAL_UART_Receive_IT8. HAL_UART_RxCpltCallback9. printf10. HAL_TIM_Base_Start_IT11. HAL_TIM_PeriodElapsedCallback12. HAL_TIM_PWM_Start13. __HAL_TIM_SET_COMPARE14. HAL_ADC_Start15. HAL_ADC_GetValue16. HAL_GPIO_EXTI_Callback17. HAL_I2C_Mem_Write18. HAL_I2C_Mem_Read19. HAL_GetTick20. __enable_irq / __disable_irq

有时候我们在项目中引入组件：import *** from ‘url’,一般都是这样引用的，但是有时候们的组件加载比较缓慢，就会出现整体白屏的情况，非常影响体验，还好react为我们提供了方法。
//在组件外u调用lazyconst SomeComponent = lazy(()=&gt;import(&#x27;url&#x27;))export function App()&#123;    return (        &lt;Suspensse fallback=&#123;&lt;Loading/&gt;&#125;&gt;            &lt;SomeComponent/&gt;        &lt;/Suspensse&gt;    )&#125;
把需要懒加载的组件都这样引入，页面加载的时候就会先展示Loading，而不影响其他的组件加载。

Vue2中watch使用方法在有些情况下，我们需要在状态变化时执行一些“副作用”：例如更改 DOM，或是根据异步操作的结果去修改另一处的状态。下面是两种侦听属性的写法：
export default &#123;    data()&#123;        return&#123;            value:1,            form:&#123;               name:&quot;zhangsan&quot;            &#125;        &#125;    &#125;,    watch:&#123;        value:&#123;            handler(newValue,oldValue)&#123;                console.log(newVaalue,oldValue);            &#125;        &#125;,        &#x27;form.name&#x27;:&#123;             handler(newValue,oldValue)&#123;                console.log(newVaalue,oldValue);            &#125;        &#125;    &#125;&#125;

Vue3中watch的使用方法
在有些情况下，我们需要在状态变化时执行一些“副作用”：例如更改 DOM，或是根据异步操作的结果去修改另一处的状态。

在组合式 API 中，我们可以使用 watch 函数在每次响应式状态发生变化时触发回调函数：
&lt;script setup&gt;import &#123; ref, watch &#125; from &#x27;vue&#x27;const question = ref(&#x27;&#x27;)const answer = ref(&#x27;Questions usually contain a question mark. ;-)&#x27;)const loading = ref(false)// 可以直接侦听一个 refwatch(question, async (newQuestion, oldQuestion) =&gt; &#123;  if (newQuestion.includes(&#x27;?&#x27;)) &#123;    loading.value = true    answer.value = &#x27;Thinking...&#x27;    try &#123;      const res = await fetch(&#x27;https://yesno.wtf/api&#x27;)      answer.value = (await res.json()).answer    &#125; catch (error) &#123;      answer.value = &#x27;Error! Could not reach the API. &#x27; + error    &#125; finally &#123;      loading.value = false    &#125;  &#125;&#125;)&lt;/script&gt;&lt;template&gt;  &lt;p&gt;    Ask a yes/no question:    &lt;input v-model=&quot;question&quot; :disabled=&quot;loading&quot; /&gt;  &lt;/p&gt;  &lt;p&gt;&#123;&#123; answer &#125;&#125;&lt;/p&gt;&lt;/template&gt;


侦听数据源类型watch 的第一个参数可以是不同形式的“数据源”：它可以是一个 ref (包括计算属性)、一个响应式对象、一个 getter 函数、或多个数据源组成的数组：

const x = ref(0)const y = ref(0)// 单个 refwatch(x, (newX) =&gt; &#123;  console.log(`x is $&#123;newX&#125;`)&#125;)// getter 函数watch(  () =&gt; x.value + y.value,  (sum) =&gt; &#123;    console.log(`sum of x + y is: $&#123;sum&#125;`)  &#125;)// 多个来源组成的数组watch([x, () =&gt; y.value], ([newX, newY]) =&gt; &#123;  console.log(`x is $&#123;newX&#125; and y is $&#123;newY&#125;`)&#125;)

注意，你不能直接侦听响应式对象的属性值，例如:
const obj = reactive(&#123; count: 0 &#125;)// 错误，因为 watch() 得到的参数是一个 numberwatch(obj.count, (count) =&gt; &#123;  console.log(`count is: $&#123;count&#125;`)&#125;)

这里需要用一个返回该属性的 getter 函数：
// 提供一个 getter 函数watch(  () =&gt; obj.count,  (count) =&gt; &#123;    console.log(`count is: $&#123;count&#125;`)  &#125;)

结构体（struct）是C语言中一种重要的用户自定义数据类型，它允许将不同的数据类型组合在一起，形成一个逻辑单元。
一、基本概念1.1 为什么需要结构体基本数据类型（int\float\char等)只能表示单一类型的数据。当需要表示一个复杂的对象（如学生、图书、点坐标）时，需要将多个不同的数据组织在一起：
//使用结构体：数据分散、难以管理char name[20];int age;float score;//使用结构体：数据聚合、逻辑清晰struct Student &#123;	char name[20];	int age;	float score;&#125;

1.2 结构体的定义struct 结构体名 &#123;  数据类型 成员名1;  数据类型 成员名2;  // ...&#125;

示例:
struct Point &#123;  int x;  int y;&#125;struct Student &#123;	char name[20];  int age;  float score;  char gender;&#125;

二、结构体变量的声明与初始化2.1 三种声明方式// 方式1:先定义结构体、再声明变量struct Point &#123;  int x;  int y;&#125;;struct Point p1, p2;// 方式2:定义结构体的同时声明变量struct Point &#123;  int x;  int y;&#125; p1, p2;// 方式3:匿名结构体（不推荐、无法复用）struct &#123;  int x;  int y;&#125; p1, p2;

2.2 初始化// 按顺序初始化struct Point p1 = &#123;10, 20&#125;;// 指定成员初始化（C99）struct Point p2 = &#123;.y = 20, .x = 10&#125;;// 部分初始化，其余为0struct Point p3 = &#123;10&#125;;  // x=10, y=0// 嵌套结构体初始化struct Student &#123;    char name[20];    int age;    struct Point location;  // 嵌套&#125;;struct Student s = &#123;&quot;Tom&quot;, 18, &#123;3, 4&#125;&#125;;

三、访问结构体成员3.1 点运算符（.)用于结构体变量：
struct (point p = &#123;10,20&#125;);printf(&quot;&amp;d,%d\n&quot;,p.x,p.y);p.x = 30;strcpy(s.name,&quot;jerry&quot;);

3.2箭头运算符（-&gt;）用于结构体指针：
struct Point p = &#123;10, 20&#125;;struct Point *ptr = &amp;p;//以下两种写法等价print(&quot;%d\n&quot;,(*ptr).x); //先解引用再用点print(&quot;%d\n, ptr-&gt;x&quot;; // 推荐写法

四、结构体内存布局4.1 内存对齐结构体在内存中并非简单地将成员大相加，编译器会进行内存对齐，以提高访问效率。
struct A &#123;  char C; // 1字节  int i;  // 4字节  char d; // 1字节&#125;;// sizeof(struct A); 通常为12，而不成6

对其规则：

每个成员的偏移量必须是该成员大小的整数倍（或对齐模数的整数倍）
结构体总大小必须是最大成员对齐数的整倍数

4.2 控制对齐// 使用 #pragma pack 修改对齐方式#pragma pack(push, 1)   // 1字节对齐struct Packed &#123;    char c;    int i;    char d;&#125;;  // sizeof = 6#pragma pack(pop)

五、结构体与指针5.1 结构体指针struct Student s = &#123;&quot;Tom&quot;, 18, 90.5&#125;;struct Student *p = &amp;s;printf(&quot;%s\n&quot;, p-&gt;name);printf(&quot;%d\n&quot;, p-&gt;age);p-&gt;age = 19;  // 通过指针修改

5.2 作为函数参数// 值传递：会复制整个结构体，开销大void printStudent(struct Student s) &#123;    printf(&quot;%s\n&quot;, s.name);&#125;// 指针传递：推荐，效率高void updateAge(struct Student *s, int newAge) &#123;    s-&gt;age = newAge;&#125;// const指针：防止修改void printStudent(const struct Student *s) &#123;    printf(&quot;%s\n&quot;, s-&gt;name);&#125;

六、结构体数组struct Student students[3] = &#123;    &#123;&quot;Tom&quot;, 18, 90.5&#125;,    &#123;&quot;Jerry&quot;, 19, 85.0&#125;,    &#123;&quot;Spike&quot;, 20, 78.5&#125;&#125;;// 遍历for (int i = 0; i &lt; 3; i++) &#123;    printf(&quot;%s: %.1f\n&quot;, students[i].name, students[i].score);&#125;// 用指针遍历struct Student *p = students;for (int i = 0; i &lt; 3; i++) &#123;    printf(&quot;%s\n&quot;, (p + i)-&gt;name);&#125;

七、typedef 与结构体// 不使用typedefstruct Point &#123;    int x, y;&#125;;struct Point p1;  // 必须写 struct// 使用typedef（推荐）typedef struct &#123;    int x, y;&#125; Point;Point p1;  // 更简洁// 带标签的typedef（可在结构体内引用自身）typedef struct Node &#123;    int data;    struct Node *next;  // 这里必须用 struct Node&#125; Node;

八、自引用结构体（链表）typedef struct Node &#123;    int data;    struct Node *next;  // 指向同类型结构体&#125; Node;// 使用Node *head = malloc(sizeof(Node));head-&gt;data = 1;head-&gt;next = malloc(sizeof(Node));head-&gt;next-&gt;data = 2;head-&gt;next-&gt;next = NULL;

九、位域（Bit Fields）用于节省内存，精确控制成员占用的位数：
struct Flags &#123;    unsigned int flag1 : 1;   // 1位    unsigned int flag2 : 1;   // 1位    unsigned int value : 6;   // 6位    unsigned int       : 0;   // 强制对齐到下一个存储单元&#125;;

用途：硬件寄存器、协议报文、位标志等。
十、结构体的复制与比较
